    int n;
    std::cin >> n;

    do {
        int d = n % 10;
        if (d >= 5) {
            std::cout << "-O|";
        } else {
            std::cout << "O-|";
        }
        d %= 5;
        for (int i = 0; i < d; ++i) {
            std::cout << "O";
        }
        std::cout << "-";
        for (int i = 4 - d; i > 0; --i) {
            std::cout << "O";
        }
        std::cout << std::endl;
        n /= 10;
    } while (n > 0);

    return 0;
}

